import{_ as t,a0 as o,w as d,s as r,I as n,x as a,a1 as i,A as l,ao as p}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const y=JSON.parse('{"title":"精通 Linux 的 ls 命令 | LCTT x X-CMD","titleTemplate":false,"description":"精通 Linux 的 ls 命令 | LCTT (201907) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"精通 Linux 的 ls 命令 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"精通 Linux 的 ls 命令 | LCTT (201907) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201907/20190724 Master the Linux -ls- command","title":"精通 Linux 的 ls 命令","tag":"201907","desc":""},"relativePath":"201907/20190724 Master the Linux -ls- command.md","filePath":"[post].md"}'),c={name:"201907/20190724 Master the Linux -ls- command.md"};function h(g,s,b,u,k,f){const e=o("Link");return d(),r("div",null,[s[40]||(s[40]=n("h1",{id:"精通-linux-的-ls-命令",tabindex:"-1"},[a("精通 Linux 的 ls 命令 "),n("a",{class:"header-anchor",href:"#精通-linux-的-ls-命令","aria-label":"Permalink to “精通 Linux 的 ls 命令”"},"​")],-1)),s[41]||(s[41]=n("blockquote",null,[n("p",null,"Linux 的 ls 命令拥有数量惊人的选项，可以提供有关文件的重要信息。")],-1)),s[42]||(s[42]=n("p",null,[n("img",{src:"https://img.linux.net.cn/data/attachment/album/201907/29/105754ii3874q2ww7lo882.jpg",alt:""})],-1)),n("p",null,[s[1]||(s[1]=n("code",null,"ls",-1)),s[2]||(s[2]=a(" 命令可以列出一个 ",-1)),i(e,{href:"https://opensource.com/article/19/7/what-posix-richard-stallman-explains"},{default:l(()=>[...s[0]||(s[0]=[a("POSIX",-1)])]),_:1}),s[3]||(s[3]=a(" 系统上的文件。这是一个简单的命令，但它经常被低估，不是它能做什么（因为它确实只做了一件事），而是你该如何优化对它的使用。",-1))]),s[43]||(s[43]=p(`<p>要知道在最重要的 10 个终端命令中，这个简单的 <code>ls</code> 命令可以排进前三，因为 <code>ls</code> 不会<em>只是</em>列出文件，它还会告诉你有关它们的重要信息。它会告诉你诸如拥有文件或目录的人、每个文件修改的时间、甚至是什么类型的文件。它的附带功能能让你了解你在哪里、附近有些什么，以及你可以用它们做什么。</p><p>如果你对 <code>ls</code> 的体验仅限于你的发行版在 <code>.bashrc</code> 中的别名，那么你可能错失了它。</p><h3 id="gnu-还是-bsd" tabindex="-1">GNU 还是 BSD？ <a class="header-anchor" href="#gnu-还是-bsd" aria-label="Permalink to “GNU 还是 BSD？”">​</a></h3><p>在了解 <code>ls</code> 的隐藏能力之前，你必须确定你正在运行哪个 <code>ls</code> 命令。有两个最流行的版本：包含在 GNU coreutils 包中的 GNU 版本，以及 BSD 版本。如果你正在运行 Linux，那么你很可能已经安装了 GNU 版本的 <code>ls</code>（LCTT 译注：几乎可以完全确定）。如果你正在运行 BSD 或 MacOS，那么你有的是 BSD 版本。本文会介绍它们的不同之处。</p><p>你可以使用 <code>--version</code> 选项找出你计算机上的版本：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ ls --version</span></span></code></pre></div><p>如果它返回有关 GNU coreutils 的信息，那么你拥有的是 GNU 版本。如果它返回一个错误，你可能正在运行的是 BSD 版本（运行 <code>man ls | head</code> 以确定）。</p><p>你还应该调查你的发行版可能具有哪些预设选项。终端命令的自定义通常放在 <code>$HOME/.bashrc</code> 或 <code>$HOME/.bash_aliases</code> 或 <code>$HOME/.profile</code> 中，它们是通过将 <code>ls</code> 别名化为更复杂的 <code>ls</code> 命令来完成的。例如：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>alias ls=&#39;ls --color&#39;</span></span></code></pre></div><p>发行版提供的预设非常有用，但它们确实很难分辨出哪些是 <code>ls</code> 本身的特性，哪些是它的附加选项提供的。你要是想要运行 <code>ls</code> 命令本身而不是它的别名，你可以用反斜杠“转义”命令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ \\ls</span></span></code></pre></div><h3 id="分类" tabindex="-1">分类 <a class="header-anchor" href="#分类" aria-label="Permalink to “分类”">​</a></h3><p>单独运行 <code>ls</code> 会以适合你终端的列数列出文件：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ ls ~/example</span></span>
<span class="line"><span>bunko        jdk-10.0.2</span></span>
<span class="line"><span>chapterize   otf2ttf.ff</span></span>
<span class="line"><span>despacer     overtar.sh</span></span>
<span class="line"><span>estimate.sh  pandoc-2.7.1</span></span>
<span class="line"><span>fop-2.3      safe_yaml</span></span>
<span class="line"><span>games        tt</span></span></code></pre></div><p>这是有用的信息，但所有这些文件看起来基本相同，没有方便的图标来快速表示出哪个是目录、文本文件或图像等等。</p><p>使用 <code>-F</code>（或 GNU 上的长选项 <code>--classify</code>）以在每个条目之后显示标识文件类型的指示符：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ ls ~/example</span></span>
<span class="line"><span>bunko         jdk-10.0.2/</span></span>
<span class="line"><span>chapterize*   otf2ttf.ff*</span></span>
<span class="line"><span>despacer*     overtar.sh*</span></span>
<span class="line"><span>estimate.sh   pandoc@</span></span>
<span class="line"><span>fop-2.3/      pandoc-2.7.1/</span></span>
<span class="line"><span>games/        tt*</span></span></code></pre></div><p>使用此选项，终端中列出的项目使用简写符号来按文件类型分类：</p>`,18)),n("ul",null,[s[23]||(s[23]=n("li",null,[a("斜杠（"),n("code",null,"/"),a("）表示目录（或“文件夹”）。")],-1)),n("li",null,[s[5]||(s[5]=a("星号（",-1)),s[6]||(s[6]=n("code",null,"*",-1)),s[7]||(s[7]=a("）表示可执行文件。这包括二进制文件（编译代码）以及脚本（具有",-1)),i(e,{href:"https://opensource.com/article/19/6/understanding-linux-permissions"},{default:l(()=>[...s[4]||(s[4]=[a("可执行权限",-1)])]),_:1}),s[8]||(s[8]=a("的文本文件）。",-1))]),s[24]||(s[24]=p("<li>符号（<code>@</code>）表示符号链接（或“别名”）。</li><li>等号（<code>=</code>）表示套接字。</li><li>在 BSD 上，百分号（<code>%</code>）表示<ruby>涂改<rt>whiteout</rt></ruby>（某些文件系统上的文件删除方法）。</li>",3)),n("li",null,[s[10]||(s[10]=a("在 GNU 上，尖括号（",-1)),s[11]||(s[11]=n("code",null,">",-1)),s[12]||(s[12]=a("）表示",-1)),s[13]||(s[13]=n("ruby",null,[a("门"),n("rt",null,"door")],-1)),s[14]||(s[14]=a("（",-1)),i(e,{href:"https://www.illumos.org/"},{default:l(()=>[...s[9]||(s[9]=[a("Illumos",-1)])]),_:1}),s[15]||(s[15]=a(" 和 Solaris上的进程间通信）。",-1))]),n("li",null,[s[17]||(s[17]=a("竖线（",-1)),s[18]||(s[18]=n("code",null,"|",-1)),s[19]||(s[19]=a("）表示 ",-1)),i(e,{href:"https://en.wikipedia.org/wiki/FIFO_(computing_and_electronics)"},{default:l(()=>[...s[16]||(s[16]=[a("FIFO",-1)])]),_:1}),s[20]||(s[20]=a(" 管道。    这个选项的一个更简单的版本是 ",-1)),s[21]||(s[21]=n("code",null,"-p",-1)),s[22]||(s[22]=a("，它只区分文件和目录。",-1))])]),s[44]||(s[44]=p(`<p>（LCTT 译注：在支持彩色的终端上，使用 <code>--color</code> 选项可以以不同的颜色来区分文件类型，但要注意如果将输出导入到管道中，则颜色消失。）</p><h3 id="长列表" tabindex="-1">长列表 <a class="header-anchor" href="#长列表" aria-label="Permalink to “长列表”">​</a></h3><p>从 <code>ls</code> 获取“长列表”的做法是如此常见，以至于许多发行版将 <code>ll</code> 别名为 <code>ls -l</code>。长列表提供了许多重要的文件属性，例如权限、拥有每个文件的用户、文件所属的组、文件大小（以字节为单位）以及文件上次更改的日期：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ ls -l</span></span>
<span class="line"><span>-rwxrwx---. 1 seth users         455 Mar  2  2017 estimate.sh</span></span>
<span class="line"><span>-rwxrwxr-x. 1 seth users         662 Apr 29 22:27 factorial</span></span>
<span class="line"><span>-rwxrwx---. 1 seth users    20697793 Jun 29  2018 fop-2.3-bin.tar.gz</span></span>
<span class="line"><span>-rwxrwxr-x. 1 seth users        6210 May 22 10:22 geteltorito</span></span>
<span class="line"><span>-rwxrwx---. 1 seth users         177 Nov 12  2018 html4mutt.sh</span></span>
<span class="line"><span>[...]</span></span></code></pre></div><p>如果你不想以字节为单位，请添加 <code>-h</code> 标志（或 GNU 中的 <code>--human</code>）以将文件大小转换为更加人性化的表示方法：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ ls --human</span></span>
<span class="line"><span>-rwxrwx---. 1 seth users    455 Mar  2  2017 estimate.sh</span></span>
<span class="line"><span>-rwxrwxr-x. 1 seth seth     662 Apr 29 22:27 factorial</span></span>
<span class="line"><span>-rwxrwx---. 1 seth users    20M Jun 29  2018 fop-2.3-bin.tar.gz</span></span>
<span class="line"><span>-rwxrwxr-x. 1 seth seth    6.1K May 22 10:22 geteltorito</span></span>
<span class="line"><span>-rwxrwx---. 1 seth users    177 Nov 12  2018 html4mutt.sh</span></span></code></pre></div><p>要看到更少的信息，你可以带有 <code>-o</code> 选项只显示所有者的列，或带有 <code>-g</code> 选项只显示所属组的列：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ ls -o</span></span>
<span class="line"><span>-rwxrwx---. 1 seth    455 Mar  2  2017 estimate.sh</span></span>
<span class="line"><span>-rwxrwxr-x. 1 seth    662 Apr 29 22:27 factorial</span></span>
<span class="line"><span>-rwxrwx---. 1 seth    20M Jun 29  2018 fop-2.3-bin.tar.gz</span></span>
<span class="line"><span>-rwxrwxr-x. 1 seth   6.1K May 22 10:22 geteltorito</span></span>
<span class="line"><span>-rwxrwx---. 1 seth    177 Nov 12  2018 html4mutt.sh</span></span></code></pre></div><p>也可以将两个选项组合使用以显示两者。</p><h3 id="时间和日期格式" tabindex="-1">时间和日期格式 <a class="header-anchor" href="#时间和日期格式" aria-label="Permalink to “时间和日期格式”">​</a></h3><p><code>ls</code> 的长列表格式通常如下所示：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>-rwxrwx---. 1 seth users         455 Mar  2  2017 estimate.sh</span></span>
<span class="line"><span>-rwxrwxr-x. 1 seth users         662 Apr 29 22:27 factorial</span></span>
<span class="line"><span>-rwxrwx---. 1 seth users    20697793 Jun 29  2018 fop-2.3-bin.tar.gz</span></span>
<span class="line"><span>-rwxrwxr-x. 1 seth users        6210 May 22 10:22 geteltorito</span></span>
<span class="line"><span>-rwxrwx---. 1 seth users         177 Nov 12  2018 html4mutt.sh</span></span></code></pre></div><p>月份的名字不便于排序，无论是通过计算还是识别（取决于你的大脑是否倾向于喜欢字符串或整数）。你可以使用 <code>--time-style</code> 选项和格式名称更改时间戳的格式。可用格式为：</p><ul><li><code>full-iso</code>：ISO 完整格式（1970-01-01 21:12:00）</li><li><code>long-iso</code>：ISO 长格式（1970-01-01 21:12）</li><li><code>iso</code>：iso 格式（01-01 21:12）</li><li><code>locale</code>：本地化格式（使用你的区域设置）</li><li><code>posix-STYLE</code>：POSIX 风格（用区域设置定义替换 <code>STYLE</code>）</li></ul><p>你还可以使用 <code>date</code> 命令的正式表示法创建自定义样式。</p><h3 id="按时间排序" tabindex="-1">按时间排序 <a class="header-anchor" href="#按时间排序" aria-label="Permalink to “按时间排序”">​</a></h3><p>通常，<code>ls</code> 命令按字母顺序排序。你可以使用 <code>-t</code> 选项根据文件的最近更改的时间（最新的文件最先列出）进行排序。</p><p>例如：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ touch foo bar baz</span></span>
<span class="line"><span>$ ls</span></span>
<span class="line"><span>bar  baz  foo</span></span>
<span class="line"><span>$ touch foo</span></span>
<span class="line"><span>$ ls -t</span></span>
<span class="line"><span>foo bar baz</span></span></code></pre></div><h3 id="列出方式" tabindex="-1">列出方式 <a class="header-anchor" href="#列出方式" aria-label="Permalink to “列出方式”">​</a></h3><p><code>ls</code> 的标准输出平衡了可读性和空间效率，但有时你需要按照特定方式排列的文件列表。</p><p>要以逗号分隔文件列表，请使用 <code>-m</code>：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>ls -m ~/example</span></span>
<span class="line"><span>bar, baz, foo</span></span></code></pre></div><p>要强制每行一个文件，请使用 <code>-1</code> 选项（这是数字 1，而不是小写的 L）：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ ls -1 ~/bin/</span></span>
<span class="line"><span>bar</span></span>
<span class="line"><span>baz</span></span>
<span class="line"><span>foo</span></span></code></pre></div><p>要按文件扩展名而不是文件名对条目进行排序，请使用 <code>-X</code>（这是大写 X）：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ ls</span></span>
<span class="line"><span>bar.xfc  baz.txt  foo.asc</span></span>
<span class="line"><span>$ ls -X</span></span>
<span class="line"><span>foo.asc  baz.txt  bar.xfc</span></span></code></pre></div><h3 id="隐藏杂项" tabindex="-1">隐藏杂项 <a class="header-anchor" href="#隐藏杂项" aria-label="Permalink to “隐藏杂项”">​</a></h3><p>在某些 <code>ls</code> 列表中有一些你可能不关心的条目。例如，元字符 <code>.</code> 和 <code>..</code> 分别代表“本目录”和“父目录”。如果你熟悉在终端中如何切换目录，你可能已经知道每个目录都将自己称为 <code>.</code>，并将其父目录称为 <code>..</code>，因此当你使用 <code>-a</code> 选项显示隐藏文件时并不需要它经常提醒你。</p><p>要显示几乎所有隐藏文件（<code>.</code> 和 <code>..</code> 除外），请使用 <code>-A</code> 选项：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ ls -a</span></span>
<span class="line"><span>.</span></span>
<span class="line"><span>..</span></span>
<span class="line"><span>.android</span></span>
<span class="line"><span>.atom</span></span>
<span class="line"><span>.bash_aliases</span></span>
<span class="line"><span>[...]</span></span>
<span class="line"><span>$ ls -A</span></span>
<span class="line"><span>.android</span></span>
<span class="line"><span>.atom</span></span>
<span class="line"><span>.bash_aliases</span></span>
<span class="line"><span>[...]</span></span></code></pre></div><p>有许多优秀的 Unix 工具有保存备份文件的传统，它们会在保存文件的名称后附加一些特殊字符作为备份文件。例如，在 Vim 中，备份会以在文件名后附加 <code>~</code> 字符的文件名保存。</p><p>这些类型的备份文件已经多次使我免于愚蠢的错误，但是经过多年享受它们提供的安全感后，我觉得不需要用视觉证据来证明它们存在。我相信 Linux 应用程序可以生成备份文件（如果它们声称这样做的话），我很乐意相信它们存在 —— 而不用必须看到它们。</p><p>要隐藏备份文件，请使用 <code>-B</code> 或 <code>--ignore-backups</code> 隐藏常用备份格式（此选项在 BSD 的 <code>ls</code> 中不可用）：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ ls</span></span>
<span class="line"><span>bar.xfc  baz.txt  foo.asc~  foo.asc</span></span>
<span class="line"><span>$ ls -B</span></span>
<span class="line"><span>bar.xfc  baz.txt  foo.asc</span></span></code></pre></div><p>当然，备份文件仍然存在；它只是过滤掉了，你不必看到它。</p><p>除非另有配置，GNU Emacs 在文件名的开头和结尾添加哈希字符（<code>＃</code>）来保存备份文件（<code>#file＃</code>）。其他应用程序可能使用不同的样式。使用什么模式并不重要，因为你可以使用 <code>--hide</code> 选项创建自己的排除项：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ ls</span></span>
<span class="line"><span>bar.xfc  baz.txt  #foo.asc#  foo.asc</span></span>
<span class="line"><span>$ ls --hide=&quot;#*#&quot;</span></span>
<span class="line"><span>bar.xfc  baz.txt  foo.asc</span></span></code></pre></div><h3 id="递归地列出目录" tabindex="-1">递归地列出目录 <a class="header-anchor" href="#递归地列出目录" aria-label="Permalink to “递归地列出目录”">​</a></h3><p>除非你在指定目录上运行 <code>ls</code>，否则子目录的内容不会与 <code>ls</code> 命令一起列出：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ ls -F</span></span>
<span class="line"><span>example/  quux*  xyz.txt</span></span>
<span class="line"><span>$ ls -R</span></span>
<span class="line"><span>quux  xyz.txt</span></span>
<span class="line"><span></span></span>
<span class="line"><span>./example:</span></span>
<span class="line"><span>bar.xfc  baz.txt  #foo.asc#  foo.asc</span></span></code></pre></div><h3 id="使用别名使其永久化" tabindex="-1">使用别名使其永久化 <a class="header-anchor" href="#使用别名使其永久化" aria-label="Permalink to “使用别名使其永久化”">​</a></h3><p><code>ls</code> 命令可能是 shell 会话期间最常使用的命令。这是你的眼睛和耳朵，为你提供上下文信息和确认命令的结果。虽然有很多选项很有用，但 <code>ls</code> 之美的一部分就是简洁：两个字符和回车键，你就知道你到底在哪里以及附近有什么。如果你不得不停下思考（更不用说输入）几个不同的选项，它会变得不那么方便，所以通常情况下，即使最有用的选项也不会用了。</p><p>解决方案是为你的 <code>ls</code> 命令添加别名，以便在使用它时，你可以获得最关心的信息。</p><p>要在 Bash shell 中为命令创建别名，请在主目录中创建名为 <code>.bash_aliases</code> 的文件（必须在开头包含 <code>.</code>）。 在此文件中，列出要创建的别名，然后是要为其创建别名的命令。例如：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>alias ls=&#39;ls -A -F -B --human --color&#39;</span></span></code></pre></div><p>这一行导致你的 Bash shell 将 <code>ls</code> 命令解释为 <code>ls -A -F -B --human --color</code>。</p><p>你不必仅限于重新定义现有命令，还可以创建自己的别名：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>alias ll=&#39;ls -l&#39;</span></span>
<span class="line"><span>alias la=&#39;ls -A&#39;</span></span>
<span class="line"><span>alias lh=&#39;ls -h&#39;</span></span></code></pre></div><p>要使别名起作用，shell 必须知道 <code>.bash_aliases</code> 配置文件存在。在编辑器中打开 <code>.bashrc</code> 文件（如果它不存在则创建它），并包含以下代码块：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>if [ -e $HOME/.bash_aliases ]; then</span></span>
<span class="line"><span>    source $HOME/.bash_aliases</span></span>
<span class="line"><span>fi</span></span></code></pre></div><p>每次加载 <code>.bashrc</code>（这是一个新的 Bash shell 启动的时候），Bash 会将 <code>.bash_aliases</code> 加载到你的环境中。你可以关闭并重新启动 Bash 会话，或者直接强制它执行此操作：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ source ~/.bashrc</span></span></code></pre></div><p>如果你忘了你是否有别名命令，<code>which</code> 命令可以告诉你：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ which ls</span></span>
<span class="line"><span>alias ls=&#39;ls -A -F -B --human --color&#39;</span></span>
<span class="line"><span>        /usr/bin/ls</span></span></code></pre></div><p>如果你将 <code>ls</code> 命令别名为带有选项的 <code>ls</code> 命令，则可以通过将反斜杠前缀到 <code>ls</code> 前来覆盖你的别名。例如，在示例别名中，使用 <code>-B</code> 选项隐藏备份文件，这意味着无法使用 <code>ls</code> 命令显示备份文件。 可以覆盖该别名以查看备份文件：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ ls</span></span>
<span class="line"><span>bar  baz  foo</span></span>
<span class="line"><span>$ \\ls</span></span>
<span class="line"><span>bar  baz  baz~  foo</span></span></code></pre></div><h3 id="做一件事-把它做好" tabindex="-1">做一件事，把它做好 <a class="header-anchor" href="#做一件事-把它做好" aria-label="Permalink to “做一件事，把它做好”">​</a></h3><p><code>ls</code> 命令有很多选项，其中许多是特定用途的或高度依赖于你所使用的终端。在 GNU 系统上查看 <code>info ls</code>，或在 GNU 或 BSD 系统上查看 <code>man ls</code> 以了解更多选项。</p><p>你可能会觉得奇怪的是，一个以每个工具“做一件事，把它做好”的前提而闻名的系统会让其最常见的命令背负 50 个选项。但是 <code>ls</code> 只做一件事：它列出文件，而这 50 个选项允许你控制接收列表的方式，<code>ls</code> 的这项工作做得非常、<em>非常</em>好。</p><hr>`,61)),n("p",null,[s[26]||(s[26]=a("via: ",-1)),i(e,{href:"https://opensource.com/article/19/7/master-ls-command"},{default:l(()=>[...s[25]||(s[25]=[a("https://opensource.com/article/19/7/master-ls-command",-1)])]),_:1})]),n("p",null,[s[31]||(s[31]=a("作者：",-1)),i(e,{href:"https://opensource.com/users/seth"},{default:l(()=>[...s[27]||(s[27]=[a("Seth Kenlon",-1)])]),_:1}),s[32]||(s[32]=a(" 选题：",-1)),i(e,{href:"https://github.com/lujun9972"},{default:l(()=>[...s[28]||(s[28]=[a("lujun9972",-1)])]),_:1}),s[33]||(s[33]=a(" 译者：",-1)),i(e,{href:"https://github.com/wxy"},{default:l(()=>[...s[29]||(s[29]=[a("wxy",-1)])]),_:1}),s[34]||(s[34]=a(" 校对：",-1)),i(e,{href:"https://github.com/wxy"},{default:l(()=>[...s[30]||(s[30]=[a("wxy",-1)])]),_:1})]),n("p",null,[s[37]||(s[37]=a("本文由 ",-1)),i(e,{href:"https://github.com/LCTT/TranslateProject"},{default:l(()=>[...s[35]||(s[35]=[a("LCTT",-1)])]),_:1}),s[38]||(s[38]=a(" 原创编译，",-1)),i(e,{href:"https://linux.cn/"},{default:l(()=>[...s[36]||(s[36]=[a("Linux中国",-1)])]),_:1}),s[39]||(s[39]=a(" 荣誉推出",-1))])])}const C=t(c,[["render",h]]);export{y as __pageData,C as default};
